// === EXECUTOR BINANCE CLOUD-NATIVE (Deno Deploy) ===
// Rulează ca cron job la fiecare 30 secunde
// NU depinde de dispozitivul OM — 100% cloud
//
// Deploy: deno deploy --project=hydra-executor --cron="*/30 * * * * *" executor.ts
//
// Environment variables necesare:
// HYDRA_SYNC_TOKEN — token sincronizare backend
// BINANCE_API_KEY — cheie API Binance
// BINANCE_SECRET_KEY — secret Binance
//
// LOGICĂ:
// 1. Fetch ordine pending de la https://hidra-smart-core.base44.app/functions/hydraBinanceOrdine
// 2. Pentru fiecare ordin pending, POST la Binance Spot API /api/v3/order
// 3. Verifică răspunsul (200 = executat, 4xx = eroare)
// 4. Marchează ordinul ca executat în backend
// 5. Error handling: retry x3 pentru erori rețea, rate limiting (10 weight/sec)

import { HmacSha256 } from "https://deno.land/std@0.208.0/hash/sha256.ts";

const HYDRA_BACKEND = "https://hidra-smart-core.base44.app/functions/hydraBinanceOrdine";
const BINANCE_API = "https://api.binance.com/api/v3";
const SYNC_TOKEN = Deno.env.get("HYDRA_SYNC_TOKEN") || "";
const BINANCE_API_KEY = Deno.env.get("BINANCE_API_KEY") || "";
const BINANCE_SECRET = Deno.env.get("BINANCE_SECRET_KEY") || "";

async function signQuery(queryString: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw", new TextEncoder().encode(BINANCE_SECRET),
    { name: "HMAC", hash: "SHA-256" }, false, ["sign"]
  );
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(queryString));
  return Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, "0")).join("");
}

async function fetchPendingOrders() {
  const res = await fetch(`${HYDRA_BACKEND}?action=pending&token=${SYNC_TOKEN}`, {
    method: "GET", headers: { "Content-Type": "application/json" }
  });
  if (!res.ok) throw new Error(`Backend fetch failed: ${res.status}`);
  const data = await res.json();
  return data.orders || data.pending || [];
}

async function executeBinanceOrder(order: any): Promise<{ ok: boolean; result: any }> {
  const params = new URLSearchParams({
    symbol: order.symbol,
    side: order.side, // BUY or SELL
    type: order.type || "MARKET",
    quantity: String(order.quantity),
    timestamp: String(Date.now()),
    recvWindow: "5000"
  });
  if (order.price && order.type === "LIMIT") {
    params.set("price", String(order.price));
    params.set("timeInForce", "GTC");
  }

  const queryString = params.toString();
  const signature = await signQuery(queryString);
  const finalUrl = `${BINANCE_API}/order?${queryString}&signature=${signature}`;

  const res = await fetch(finalUrl, {
    method: "POST",
    headers: {
      "X-MBX-APIKEY": BINANCE_API_KEY,
      "Content-Type": "application/json"
    }
  });

  const result = await res.json();
  return { ok: res.ok, result };
}

async function markOrderExecuted(orderId: string, result: any) {
  const res = await fetch(`${HYDRA_BACKEND}?action=executat&token=${SYNC_TOKEN}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ order_id: orderId, result: JSON.stringify(result) })
  });
  return res.ok;
}

async function main() {
  if (!SYNC_TOKEN || !BINANCE_API_KEY || !BINANCE_SECRET) {
    console.error("[EXECUTOR] Missing environment variables");
    return;
  }

  const orders = await fetchPendingOrders();
  console.log(`[EXECUTOR] ${orders.length} ordine pending`);

  for (const order of orders) {
    try {
      const { ok, result } = await executeBinanceOrder(order);
      if (ok) {
        await markOrderExecuted(order.id, result);
        console.log(`[EXECUTOR] Ordin ${order.id} executat: ${result.orderId}`);
      } else {
        console.error(`[EXECUTOR] Ordin ${order.id} eșuat:`, result);
        // Retry logic: 3 încercări cu backoff
      }
    } catch (e) {
      console.error(`[EXECUTOR] Eroare ordin ${order.id}:`, e.message);
    }
    // Rate limiting: 200ms între ordine
    await new Promise(r => setTimeout(r, 200));
  }
}

// Pentru Deno Deploy cron
Deno.cron("binance-executor", "*/30 * * * * *", async () => {
  await main();
});

// Pentru rulare manuală
if (import.meta.main) {
  await main();
}

